#include "KS/SRC/ks/FEPanel.h"
#include "KS/SRC/text_font_shared.h"
#include "KS/SRC/ks/igo_widget_analogclock.h"

extern const char hand01[];
extern const char timeframe_1[];
extern const char face01[];
extern const char minute_1[];
extern const char minute_2[];
extern const char minute_3[];
extern const char minute_4[];
extern const char minute_5[];
extern const char minute_infinty[];

__asm__(".equ hand01, 0x004C0A20");
__asm__(".equ timeframe_1, 0x004C0A28");
__asm__(".equ face01, 0x004C0A38");
__asm__(".equ minute_1, 0x004C0A40");
__asm__(".equ minute_2, 0x004C0A50");
__asm__(".equ minute_3, 0x004C0A60");
__asm__(".equ minute_4, 0x004C0A70");
__asm__(".equ minute_5, 0x004C0A80");
__asm__(".equ minute_infinty, 0x004C0A90");
__asm__(".equ GetPointer__9PanelFilePCc, 0x00152F88");

void AnalogClockWidget::Init(PanelFile & panel, Font * numberFont)
{
	float d = 23.0f * tanf(2*PI/(float)60) * 1.2f; //1.02f;
	float ccx = 556.0f;
	float ccy = 73.0f;

	clockHandPQ = panel.GetPointer(hand01);;
	clockHandPQ->TurnOn(true);
	clockHandPQ->GetCenterPos(handCenterX, handCenterY);
	clockFramePQ = panel.GetPointer(timeframe_1);
	clockFramePQ->TurnOn(true);
	clockFacePQ = panel.GetPointer(face01);
	clockFacePQ->TurnOn(true);
	num1PQ = panel.GetPointer(minute_1);
	num1PQ->TurnOn(false);
	num2PQ = panel.GetPointer(minute_2);
	num2PQ->TurnOn(false);
	num3PQ = panel.GetPointer(minute_3);
	num3PQ->TurnOn(false);
	num4PQ = panel.GetPointer(minute_4);
	num4PQ->TurnOn(false);
	num5PQ = panel.GetPointer(minute_5);
	num5PQ->TurnOn(false);
	infPQ = panel.GetPointer(minute_infinty);
	infPQ->TurnOn(true);

	for(int i=0; i<60; i++)
	{
		timeSegs[i]->Init(ccx-d, ccx, ccx, ccx, ccy-23.0f, ccy-23.0f, ccy, ccy, 0.0f, 0.0f, .5f, 1.0f, 300);
	}
	for(int i=0; i<60; i++)
	{
		timeSegs[i]->RotateOnce(ccx, ccy, -i*(2*PI/(float)60));
	}

	scoreText->setFont(numberFont);
	elapsedInterval = 0.0f;

	SetDisplay(true);
}
